  const domainOptions = state.growth.domains.map((domain) => `<option value="${escapeHtml(domain.id)}">${escapeHtml(domain.name)}</option>`).join('');
  const legacyOption = goal?.area && !state.growth.domains.some((domain) => domain.id === goal.area) ? `<option value="${escapeHtml(goal.area)}">${escapeHtml(goalAreaLabel(goal.area))}</option>` : '';
