  const isEditing = Boolean(book);
  $('#bookForm').reset();
  $('#bookDialogEyebrow').textContent = isEditing ? 'EDIT BOOK' : 'NEW BOOK';
  $('#bookDialogTitle').textContent = isEditing ? '책 정보를 다듬어보세요.' : '서재에 책을 추가해요.';
  $('#saveBookButton').textContent = isEditing ? '수정 저장' : '책 저장';
  $('#removeCoverOption').hidden = !isEditing || !book.cover;
  if (isEditing) { $('#bookTitle').value = book.title; $('#bookSubtitle').value = book.subtitle || ''; $('#bookOriginalTitle').value = book.originalTitle || ''; $('#bookAuthor').value = book.author || ''; $('#bookPublishedYear').value = book.publishedYear || ''; $('#bookFormat').value = book.format || 'paper'; $('#bookPlatform').value = book.platform || ''; $('#bookStatus').value = book.status; $('#bookFinishedYear').value = book.finishedYear || ''; $('#bookFinishedMonth').value = book.finishedMonth || ''; $('#bookFinishedDay').value = book.finishedDay || ''; if (/^https?:\/\//.test(book.cover)) $('#bookCoverUrl').value = book.cover; }
