function openBookDetail(id) { const book = state.books.find((item) => item.id === id); if (!book) return; activeBookId = id; const linkedKnowledge = state.knowledge.filter((card) => (card.references || []).includes(`book:${book.id}`)); $('#bookDetailMeta').textContent = `MY LIBRARY · ${bookStatuses[book.status] || '책'}`; $('#bookDetailTitle').textContent = book.title; $('#bookDetailBody').innerHTML = `<div class="book-detail-layout"><div class="book-detail-cover">${book.cover ? `<img src="${book.cover}" alt="${escapeHtml(book.title)} 표지">` : `<span>${escapeHtml(book.title)}</span>`}</div><div>${book.originalTitle ? `<p class="book-detail-original-title">${escapeHtml(book.originalTitle)}</p>` : ''}<p class="book-detail-author">${escapeHtml(book.author || '저자 미입력')}</p><section class="book-detail-review"><h3>나의 감상</h3><p class="${book.review ? '' : 'is-empty'}">${book.review ? escapeHtml(book.review) : '아직 남긴 감상이 없어요. 수정 버튼을 눌러 이 책을 읽으며 떠오른 생각을 기록해보세요.'}</p></section>${linkedKnowledge.length ? `<section class="book-detail-knowledge"><h3>메모 · ${linkedKnowledge.length}</h3><div>${linkedKnowledge.map((card) => { const location = formatBookLocation((card.bookReferences || []).find((ref) => ref.bookId === book.id)?.location); return `<button type="button" data-open-linked-knowledge="${card.id}"><span>${escapeHtml(card.title)}${location ? `<small>${escapeHtml(location)}</small>` : ''}</span><b>→</b></button>`; }).join('')}</div></section>` : ''}</div></div>`; $('#bookDetailDialog').showModal(); }
