function openLoreDetail(loreId) { const content = activeContent(); const item = content?.lore.find((lore) => lore.id === loreId); if (!item) return; const parents = loreParentIds(item).map((id) => content.lore.find((lore) => lore.id === id)).filter(Boolean); const children = content.lore.filter((lore) => loreParentIds(lore).includes(item.id)); const relationTitle = item.type === 'group' ? '구성원' : '연결된 설정'; const related = children.length ? `<section class="lore-detail-relations"><h3>${relationTitle} <span>${children.length}</span></h3><div>${children.map((child) => `<button type="button" class="lore-relation-chip" data-open-lore-detail="${child.id}">${child.type === 'character' ? `<span class="lore-relation-avatar">${child.image ? `<img src="${child.image}" alt="${escapeHtml(child.name)} 사진" />` : escapeHtml(child.name.slice(0, 1))}</span>` : ''}<span class="lore-relation-name">${escapeHtml(child.name)}</span><small>${loreTypes[child.type] || '설정'}</small><b>→</b></button>`).join('')}</div></section>` : ''; const affiliations = parents.length ? `<section class="lore-detail-relation"><span>소속</span>${parents.map((parent) => `<button type="button" data-open-lore-detail="${parent.id}">${escapeHtml(parent.name)} <small>${loreTypes[parent.type] || '설정'}</small><b>→</b></button>`).join('')}</section>` : ''; const portrait = item.type === 'character' ? `<div class="lore-detail-profile">${item.image ? `<img src="${item.image}" alt="${escapeHtml(item.name)} 사진" />` : `<span>${escapeHtml(item.name.slice(0, 1))}</span>`}</div>` : ''; $('#loreDetailType').textContent = loreTypes[item.type] || '설정'; $('#loreDetailTitle').textContent = item.name; $('#loreDetailBody').innerHTML = `${portrait}${affiliations}${item.note ? `<p class="lore-detail-note">${escapeHtml(item.note)}</p>` : '<p class="lore-detail-note is-empty">아직 적어둔 설명이 없어요.</p>'}${related}`; $('#editLoreFromDetailButton').dataset.editLore = item.id; $('#deleteLoreFromDetailButton').dataset.deleteLore = item.id; $('#loreDetailDialog').showModal(); }
